const $=s=>document.querySelector(s);const tokenKey='lac_admin_token';
const statuses=['new','confirmed','processing','shipped','delivered','completed','cancelled','refunded'];
const fmt=n=>Number(n||0).toLocaleString();
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function token(){return sessionStorage.getItem(tokenKey)||''}
function showDashboard(){ $('#login').classList.add('hidden'); $('#dashboard').classList.remove('hidden'); loadOrders(); loadProducts(); }
async function api(path,opts={}){const r=await fetch(path,{...opts,headers:{'Content-Type':'application/json',Authorization:`Bearer ${token()}`,...(opts.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Request failed');return d}
$('#loginForm').onsubmit=async e=>{e.preventDefault();$('#loginMsg').textContent='Signing in…';try{const r=await fetch('/.netlify/functions/admin-login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:$('#email').value,password:$('#password').value})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Unable to sign in');sessionStorage.setItem(tokenKey,d.access_token);showDashboard()}catch(err){$('#loginMsg').textContent=err.message}};
$('#logout').onclick=()=>{sessionStorage.removeItem(tokenKey);location.reload()};
async function loadOrders(){try{const {orders=[]}=await api('/.netlify/functions/admin-orders');const paid=orders.filter(x=>x.payment_status==='paid');const pending=orders.filter(x=>!['paid','refunded'].includes(x.payment_status));const revenue=paid.reduce((a,x)=>a+Number(x.total_amount||0),0);$('#totalOrders').textContent=orders.length;$('#paidOrders').textContent=paid.length;$('#pendingOrders').textContent=pending.length;$('#revenue').textContent=`KSh ${fmt(revenue)}`;$('#orders').innerHTML=orders.map(o=>`<tr><td><strong>${esc(o.order_number)}</strong></td><td>${esc(o.customer_name)}<br><small>${esc(o.customer_phone)}</small></td><td>${o.total_amount?`KSh ${fmt(o.total_amount)}`:'Price on request'}</td><td>${esc(o.payment_status)}</td><td>${esc(o.order_status)}</td><td>${new Date(o.created_at).toLocaleString()}</td><td><select data-id="${esc(o.id)}" class="status"><option value="">Update…</option>${statuses.map(s=>`<option value="${s}">${s}</option>`).join('')}</select></td></tr>`).join('');document.querySelectorAll('.status').forEach(s=>s.onchange=async()=>{if(!s.value)return;try{await api(`/.netlify/functions/admin-update-order?id=${encodeURIComponent(s.dataset.id)}`,{method:'PATCH',body:JSON.stringify({order_status:s.value})});loadOrders()}catch(err){alert(err.message)}})}catch(err){if(/Unauthorized|Admin access/.test(err.message)){sessionStorage.removeItem(tokenKey);location.reload()}else alert(err.message)}}
async function loadProducts(){try{const {products=[]}=await api('/.netlify/functions/admin-products');$('#products').innerHTML=products.map(p=>`<tr><td><strong>${esc(p.name)}</strong><br><small>${esc(p.category||'')}</small></td><td>${esc(p.slug)}</td><td><input class="price-input" data-price-id="${esc(p.id)}" type="number" min="0" step="0.01" value="${p.price??''}" placeholder="Price on request"></td><td>${esc(p.currency||'KES')}</td><td><select data-active-id="${esc(p.id)}"><option value="true" ${p.is_active?'selected':''}>Active</option><option value="false" ${!p.is_active?'selected':''}>Hidden</option></select></td><td><button class="btn secondary save-product" data-id="${esc(p.id)}">Save</button></td></tr>`).join('');document.querySelectorAll('.save-product').forEach(b=>b.onclick=async()=>{const id=b.dataset.id;const price=document.querySelector(`[data-price-id="${CSS.escape(id)}"]`).value;const active=document.querySelector(`[data-active-id="${CSS.escape(id)}"]`).value==='true';try{b.disabled=true;b.textContent='Saving…';await api(`/.netlify/functions/admin-products?id=${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({price,is_active:active})});b.textContent='Saved';setTimeout(()=>{b.textContent='Save';b.disabled=false},1200)}catch(err){b.disabled=false;b.textContent='Save';alert(err.message)}})}catch(err){alert(err.message)}}
$('#productForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const body=Object.fromEntries(f.entries());body.is_active=true;try{await api('/.netlify/functions/admin-products',{method:'POST',body:JSON.stringify(body)});e.target.reset();$('#productMsg').textContent='Product added successfully.';loadProducts()}catch(err){$('#productMsg').textContent=err.message}};
if(token())showDashboard();
